function strategyLibraryHTML(){const count=new Set(STRATEGY_COURSES.flatMap(c=>c.videos.map(v=>v.id))).size;return `<details class="strategy-library"><summary>Estratégia Concursos · ${count} videoaulas públicas em ${STRATEGY_COURSES.length} disciplinas</summary><p>Aulas e cursos transmitidos publicamente pelo canal oficial do Estratégia Concursos, organizados como material complementar. Acesso disponível em qualquer cargo. Esta biblioteca não dá acesso à assinatura ou aos cursos pagos do produtor.</p><p><a href="https://gratis.estrategiaconcursos.com.br/" target="_blank" rel="noopener noreferrer">Materiais gratuitos oficiais ↗</a> · <a href="https://www.estrategiaconcursos.com.br/" target="_blank" rel="noopener noreferrer">Cursos e assinaturas do produtor ↗</a></p><label>Buscar disciplina ou videoaula<input id="strategy-search" class="search" placeholder="Ex.: Português, Previdenciário, Redes…"></label><p id="strategy-search-count" aria-live="polite"></p>${STRATEGY_COURSES.map(c=>`<details class="strategy-subject" data-strategy-subject><summary>${esc(c.category)} · ${c.videos.length} vídeo(s)</summary>${c.videos.map(v=>`<article class="video-choice" data-strategy-search="${esc(c.category+' '+v.title)}"><div><strong>${esc(v.title)}</strong><small>${esc(v.by)} · ${Math.floor(v.duration/60)} min${state.externalLessons?.done?.[v.id]?' · Concluída ✓':''}</small></div><button data-strategy-video="${v.id}">Assistir →</button></article>`).join('')}</details>`).join('')}<p class="muted">Disponibilidade pública consultada em 12/11/2026. O canal pode retirar uma transmissão ou restringir a incorporação. Nesse caso, use o link oficial do YouTube. Uma aula de outra banca pode ajudar na disciplina, mas não substitui a conferência do edital do seu cargo.</p></details>`}
function bindStrategySearch(){const input=$('#strategy-search');if(!input)return;input.oninput=()=>{const q=normalize(input.value);let count=0;document.querySelectorAll('[data-strategy-subject]').forEach(subject=>{let visible=0;subject.querySelectorAll('[data-strategy-search]').forEach(card=>{card.hidden=!normalize(card.dataset.strategySearch).includes(q);if(!card.hidden){visible++;count++}});subject.hidden=!visible;if(q)subject.open=!!visible});$('#strategy-search-count').textContent=count+' resultado(s)'}}
function openStrategyVideo(id){const v=STRATEGY_COURSES.flatMap(c=>c.videos).find(v=>v.id===id);if(!v)return;active={id:'strategy-'+id,title:v.title};state.externalLessons??={done:{},notes:{}};state.externalLessons.done??={};state.externalLessons.notes??={};$('#lesson-content').innerHTML=`<span class="eyebrow">ESTRATÉGIA CONCURSOS · AULA PÚBLICA COMPLEMENTAR</span><h2>${esc(v.title)}</h2>${videoHTML(id)}<p>${esc(v.by)} · <a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">Abrir no YouTube ↗</a></p><p>Assista por partes, anote os conceitos centrais e resolva questões da disciplina. Verifique a data da legislação citada e a referência do seu edital.</p><label>Suas anotações<textarea id="strategy-notes">${esc(state.externalLessons.notes[id]||'')}</textarea></label><button id="strategy-complete" class="study">${state.externalLessons.done[id]?'Desmarcar conclusão':'Marcar aula concluída ✓'}</button>`;$('#strategy-notes').oninput=e=>{state.externalLessons.notes[id]=e.target.value;save()};$('#strategy-complete').onclick=()=>{if(state.externalLessons.done[id])delete state.externalLessons.done[id];else state.externalLessons.done[id]=today();save();render();openStrategyVideo(id)};if(!$('#lesson').open)$('#lesson').showModal();monitorVideo(id,active.id)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-strategy-video]');if(b)openStrategyVideo(b.dataset.strategyVideo)});
